 IF NOT ((SELECT coalesce(jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),'not_null',attnotnull) ORDER BY attname COLLATE "C"),'[]'::jsonb) FROM pg_attribute WHERE attrelid=to_regclass('public.event_interests') AND attnum>0 AND NOT attisdropped) = '[{"name":"attribution","type":"jsonb","not_null":true},{"name":"contact_consent_at","type":"timestamp with time zone","not_null":true},{"name":"created_at","type":"timestamp with time zone","not_null":true},{"name":"decision","type":"text","not_null":true},{"name":"email","type":"text","not_null":false},{"name":"event_id","type":"text","not_null":true},{"name":"id","type":"uuid","not_null":true},{"name":"intake_status","type":"text","not_null":false},{"name":"invitation_consent","type":"boolean","not_null":true},{"name":"invitation_consent_at","type":"timestamp with time zone","not_null":false},{"name":"invitation_withdrawn_at","type":"timestamp with time zone","not_null":false},{"name":"name","type":"text","not_null":true},{"name":"owner_key","type":"text","not_null":true},{"name":"phone","type":"text","not_null":false},{"name":"policy_version","type":"text","not_null":true},{"name":"processing_status","type":"text","not_null":true},{"name":"source","type":"text","not_null":true},{"name":"submission_id","type":"uuid","not_null":true},{"name":"unsubscribe_hash","type":"text","not_null":true},{"name":"updated_at","type":"timestamp with time zone","not_null":true},{"name":"user_id","type":"text","not_null":false},{"name":"visitor_hash","type":"text","not_null":false}]'::jsonb AND (SELECT coalesce(jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),'not_null',attnotnull) ORDER BY attname COLLATE "C"),'[]'::jsonb) FROM pg_attribute WHERE attrelid=to_regclass('public.event_interest_limits') AND attnum>0 AND NOT attisdropped) = '[{"name":"count","type":"integer","not_null":true},{"name":"expires_at","type":"timestamp with time zone","not_null":true},{"name":"key","type":"text","not_null":true}]'::jsonb AND (SELECT coalesce(jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),'not_null',attnotnull) ORDER BY attname COLLATE "C"),'[]'::jsonb) FROM pg_attribute WHERE attrelid=to_regclass('public.events') AND attnum>0 AND NOT attisdropped AND attname IN ('admission_policy','visibility')) = '[{"name":"admission_policy","type":"text","not_null":true},{"name":"visibility","type":"text","not_null":true}]'::jsonb) THEN RAISE EXCEPTION 'Unexpected interest or admission schema'; END IF;
 IF EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename IN ('event_interests','event_interest_limits')) THEN RAISE EXCEPTION 'Interest policies must remain server-only'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class WHERE oid IN ('public.event_interests'::regclass,'public.event_interest_limits'::regclass) AND NOT relrowsecurity) THEN RAISE EXCEPTION 'Interest tables require RLS'; END IF;
END $preserved$;
DO $privileges$ DECLARE r text; BEGIN
 IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid IN ('public.event_interests'::regclass,'public.event_interest_limits'::regclass) AND a.grantee=0) THEN RAISE EXCEPTION 'Interest tables expose PUBLIC grants'; END IF;
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
   IF (has_table_privilege(r,'public.event_interests','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege(r,'public.event_interest_limits','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) THEN RAISE EXCEPTION 'Interest table grants are unsafe'; END IF;
  END IF;
 END LOOP;
END $privileges$;
COMMIT;
